/* =========================================================================
   CALCS
   ========================================================================= */
const CALCS={
 construct:{
  hint:'Change the store count and see which construct row applies.',
  ins:[{k:'n',nm:'Number of stores',type:'range',min:1,max:1000,step:1,def:40}],
  run:v=>{
    const n=+v.n; let r;
    if(n<=1) r=['Single / independent store','Store owner','Direct store-level relationship'];
    else if(n<=10) r=['Small chain (2–10)','Owner / small buying team','Direct negotiation + store-wise execution'];
    else if(n<=100) r=['Regional chain (10–100)','Central buyer + regional teams','Regional negotiations, centralised listing'];
    else if(n<=500) r=['Large regional / national chain (100–500)','Central category / procurement team','Central listing + region/store execution'];
    else r=['National / pan-India chain (500+)','Central buying + category management','National agreements, centralised promotions, store-level execution'];
    return 'Stores = '+n+'<span class="big">'+r[0]+'</span>'+
      '<span class="vd ok">Decides: '+r[1]+'</span>'+
      '<span class="vd">FMCG approach: '+r[2]+'</span>'+
      '<span class="vd warn">This is the construct only. Classify the format (hyper / super / mini / cash & carry) separately by store size.</span>';}},
 layout:{
  hint:'Describe the store and see which layout fits.',
  ins:[{k:'m',nm:'Main shopping mission',type:'select',opts:[['list','Everyday, list-driven'],['browse','Browsing / discovery'],['mixed','Several missions in one store']],def:'list'},
       {k:'s',nm:'Store type',type:'select',opts:[['dense','High-SKU (grocery, pharmacy, convenience)'],['dept','Multi-department large format'],['fashion','Fashion / lifestyle'],['premium','Premium / boutique']],def:'dense'}],
  run:v=>{
    let L,why;
    if(v.m==='mixed'){L='Hybrid';why='Grid for the core categories, free-flow or loop for featured zones, as in a hypermarket.';}
    else if(v.s==='dense'){L='Grid';why='Parallel aisles maximise density and make list shopping fast.';}
    else if(v.s==='dept'){L='Spine';why='One main aisle with departments either side gives clear navigation at scale.';}
    else if(v.s==='premium'){L='Free-flow';why='Flexible fixtures, no rigid aisles: an open, organic, premium feel.';}
    else {L=v.m==='list'?'Loop / racetrack':'Loop or free-flow';why='Loop guides shoppers past every category on a defined path; free-flow lets them wander. Choose by whether you want the path controlled.';}
    const warn=(v.m==='list'&&(v.s==='fashion'||v.s==='premium'))?'<span class="vd warn">List-driven missions rarely suit fashion floors: check the mission.</span>':'';
    return 'Mission + store type →<span class="big">'+L+'</span><span class="vd ok">'+why+'</span>'+warn;}}
};

